"„Die Mauer hält die Monster draußen. Solange du drinnen bist, bist du sicher.“": "„De muur houdt de monsters buiten. Zolang je binnen bent, ben je veilig.”",
"„Die Wildschweine fressen mir die Rüben weg. Wenn du welche siehst, jag sie!“": "„De wilde zwijnen eten mijn knollen op. Als je er een ziet, jaag ze weg!”",
"„Hast du schon mal einen Drachen gesehen? Lian sagt, am Feuerberg gibt es welche.“": "„Heb je ooit een draak gezien? Lian zegt dat er bij de Vuurberg een paar zijn.”",
"„Früher war Kazehana eine ruhige Stadt. Dann kamen die Steine.“": "„Vroeger was Kazehana een rustige stad. Toen kwamen de stenen.”",
"„Jeder Stein hat seine eigene Seele. Und jeder lässt etwas anderes zurück.“": "„Elke steen heeft zijn eigen ziel. En elke steen laat iets anders achter.”",
