"Stadt · sicherer Ort": "Stad · veilige plek",
"Lager · sicherer Ort": "Kamp · veilige plek",
"Die große Stadt Kazehana mit den grünen Sonnenwiesen.": "De grote stad Kazehana met de groene Zonneweiden.",
"Dichter Nadelwald mit Banditen, Spinnen und Bären. Spinnenhöhle und Banditenkeller.": "Dicht naaldbos met bandieten, spinnen en beren. Spinnengrot en Banditenkelder.",
"Staubiges Tal der Orks und Skorpione. Orkfestung.": "Stoffig dal van orks en schorpioenen. Orkvesting.",
"Graue Aschenebene mit Ogern und Dämonen. Totengruft.": "Grijze asvlakte met ogers en demonen. Dodengrafkelder.",
"Eisige Gipfel mit Eiswölfen, Yetis und Frostgeistern. Eisgrotte.": "IJzige pieken met ijswolven, yeti's en vorstgeesten. IJsgrot.",
"Nebliges Moor voller Untoter, Hexen und Ghule.": "Nevelig moeras vol ondoden, heksen en ghouls.",
"Schwarzer Basalt und Lavaflüsse, Golems, Feuerdämonen und Drachen. Drachenhort.": "Zwart basalt en lavarivieren, golems, vuurdemonen en draken. Drakenhorst.",
"Du wirbelst um dich selbst, triffst alle Gegner im Umkreis und betäubst sie kurz.": "Je tolt rond, raakt alle vijanden in de buurt en verdooft ze kort.",
"Buff: Blitze zucken um dich. Mehr Angriffstempo und Lauftempo.": "Buff: Bliksems knetteren om je heen. Meer aanvals- en loopsnelheid.",
"Erdbeben": "Aardbeving",
"Du stampfst auf und der Boden bebt: Alle Gegner um dich werden {0} s betäubt.": "Je stampt en de grond beeft: alle vijanden om je heen worden {0} s verdoofd.",
"Starker Körper": "Sterk lichaam",
"Buff: Dein Körper wird hart wie Stein. Mehr Verteidigung und weniger erlittener Schaden.": "Buff: Je lichaam wordt hard als steen. Meer verdediging en minder ontvangen schade.",
"Geistesschlag": "Geestesslag",
"Ein gebündelter Schlag mit voller Kraft auf ein einzelnes Ziel. Sehr hoher Schaden.": "Een gebundelde slag met volle kracht op één doel. Zeer hoge schade.",
"Kriegsschrei": "Strijdkreet",
"Ein Schrei, der Gegner lähmt: Sie werden langsamer und nehmen mehr Schaden.": "Een kreet die vijanden verlamt: ze worden trager en krijgen meer schade.",
"Du drehst dich mit beiden Dolchen und triffst alle Gegner um dich.": "Je draait met beide dolken rond en raakt alle vijanden om je heen.",
"Schattensprung": "Schaduwsprong",
"Du springst durch die Schatten nach vorn und schneidest alles auf dem Weg.": "Je springt door de schaduwen naar voren en snijdt alles op je pad.",
"Lähmende Klinge": "Verlammende kling",
"Ein Stich in die Sehnen: Das Ziel ist {0} s betäubt und {1} s vergiftet.": "Een steek in de pezen: het doel is {0} s verdoofd en {1} s vergiftigd.",
"Schattenmantel": "Schaduwmantel",
"Buff: Schatten hüllen dich ein. Mehr Ausweichen und mehr kritische Treffer.": "Buff: Schaduwen hullen je in. Meer ontwijken en meer kritieke treffers.",
"Buff: Drachenkraft fließt in dich. Mehr Angriff und mehr Fertigkeitsschaden.": "Buff: Drakenkracht stroomt door je heen. Meer aanval en meer vaardigheidsschade.",
"Geisterfaust": "Geestenvuist",
"Eine Faust aus Geisterkraft trifft ein Ziel und betäubt es {0} s.": "Een vuist van geestkracht raakt een doel en verdooft het {0} s.",
"Windfessel": "Windboei",
"Wirbelnder Wind fesselt Gegner um dich: Sie werden langsamer und verwundbar.": "Wervelende wind boeit vijanden om je heen: ze worden trager en kwetsbaar.",
"Segen": "Zegen",
"Buff: Weniger erlittener Schaden, Leben regeneriert sich, mehr kritische Treffer.": "Buff: Minder ontvangen schade, leven regenereert, meer kritieke treffers.",
"Heilung": "Genezing",
"Heilt einen Teil deines Lebens und gibt dir danach mehr Angriff.": "Geneest een deel van je leven en geeft je daarna meer aanval.",
"Schutzgeist": "Beschermgeest",
