"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "Nauwelijks zijn de honden weg of de vossen sluipen om de stallen. Jaag ze terug de weiden in",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "De wilde zwijnen vreten de oogst van de boeren op. Een winter zonder voorraad zou ons einde zijn",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "Aan de rand van de weiden gloeit een steen van woede. Zijn woede maakt de dieren razend – sla hem kapot",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "Goed dat Bao je stuurt. Bandieten overvallen elke handelaar op het bospad. Verjaag ze",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "De zwijnen hier hebben doornen in plaats van borstels. Ze verscheuren onze vallen – en de vallenzetters",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "Diep in het bos spinnen reuzenspinnen hun webben over de paden. Brand ze weg als het moet",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "Midden in het bos groeit een steen van doornen. Zijn ranken verstikken elke boom. Vernietig hem",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "Stuurt Hagen je? Kom dan, de orks staan al voor onze palissaden. Verzwak hun leger",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "De orks houden hyena's als honden en hitsen ze op onze verkenners. Schakel de meute uit",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "Stuurt Idris je? De goden zijn Sahra goedgezind. De cobra's loeren bij elke waterplaats",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "Hoor je dat geratel? Ratelslangen. Honderden. De karavanen durven niet meer te vertrekken",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "Op de Vorsttop zijn yeti's gezien zo groot als huizen. Breng hun vachten als bewijs",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "De mammoeten zijn razend sinds de vorst niet wijkt. Ze vertrappen onze voorraadhutten",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Waar de steen van de stilte staat, verstomt elk lied. Breng de klank terug op de top",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "De laatste en machtigste van alle zielenstenen. Vernietig hem en de stenen houden op met groeien",
