"Aus dem Rauch schießen Rußschützen, bevor man sie sieht. Hol sie aus den verbrannten Kronen": "Roetschutters schieten uit de rook voor je ze ziet. Haal ze uit de verbrande kruinen",
"Graue Netze": "Grijze webben",
"Zwei Steine der Gier locken die Räuber an wie Glut die Motten. Zerschlage sie": "Twee stenen van de hebzucht trekken rovers aan als gloed de motten. Sla ze kapot",
"Rußgraue Jäger": "Roetgrijze jagers",
"Rußluchse sind in der Asche unsichtbar. Unsere Köhler kommen nicht mehr heim. Sei wachsamer als sie": "Roetlynxen zijn onzichtbaar in de as. Onze kolenbranders komen niet meer thuis. Wees waakzamer dan zij",
"Kohlenbären": "Kolenberen",
"Knochen im Sand": "Botten in het zand",
"Ascan schickt dich? Dann komm, die Beinbrecher stehen schon vor unserem Ring. Brich ihre Reihen": "Stuurt Ascan je? Kom dan, de botbrekers staan al voor onze ring. Breek hun gelederen",
"Aashyänen": "Aashyena's",
"Die Hyänen folgen den Beinbrechern und fressen, was diese liegen lassen. Erledige die Meute": "De hyena's volgen de botbrekers en vreten wat die laten liggen. Schakel de meute uit",
"Die Knochenruferinnen": "De botroepsters",
"Die Ruferinnen singen die Gebeine aus dem Sand. Ohne ihren Gesang bleiben die Toten liegen": "De roepsters zingen het gebeente uit het zand. Zonder hun gezang blijven de doden liggen",
"Zwei schwarze Steine ragen aus den Dünen, und die Knochen sammeln sich darum. Nimm ihnen ihre Mitte": "Twee zwarte stenen steken uit de duinen en de botten verzamelen zich eromheen. Neem ze hun middelpunt af",
"Bleiche Stachel": "Bleke angels",
"Die Knochenhauptmänner": "De botkapiteins",
"Die Beinbrecher gehorchen Hauptmännern in alten Rüstungen. Fällst du sie, zerfällt das Heer": "De botbrekers gehoorzamen kapiteins in oude harnassen. Vel ze en het leger valt uiteen",
"Ein Stein der Asche verbrennt die Wüste von innen. Lösch ihn aus, bevor nur Staub bleibt": "Een steen van as verbrandt de woestijn van binnenuit. Doof hem voor er alleen stof overblijft",
"Rot am Horizont": "Rood aan de horizon",
"Ossian hat recht, dich zu schicken. Blutoger stampfen jede Nacht gegen unsere Inseln. Halte sie fern": "Ossian doet er goed aan je te sturen. Bloedreuzen stampen elke nacht tegen onze eilanden. Hou ze weg",
"Wargrudel der Steppe": "Wargroedel van de steppe",
"Steppenwargs jagen in großen Rudeln durch das rote Gras. Jag das Rudel, bevor es uns jagt": "Steppewargs jagen in grote roedels door het rode gras. Jaag op de roedel voor hij op ons jaagt",
"Blutdämonen": "Bloeddemonen",
"Aus den roten Tümpeln steigen Blutdämonen. Treib sie zurück in die Tiefe": "Uit de rode poelen stijgen bloeddemonen op. Drijf ze terug de diepte in",
"Die Steine der Glut heizen die Tümpel auf, bis sie kochen. Lösche sie aus": "De gloedstenen verhitten de poelen tot ze koken. Doof ze",
"Blutmäuler": "Bloedmuilen",
"Blutmäuler bewachen die Tümpel der Dämonen. Wer sie besiegt, kann den Quellen nahe kommen": "Bloedmuilen bewaken de poelen van de demonen. Wie ze verslaat, kan de bronnen naderen",
"Die Klippenfeste": "De klippenvesting",
"Kobras im Fels": "Cobra's in de rots",
"Das Rasseln in der Nacht": "Het geratel in de nacht",
"Hörst du das Rasseln an den Klippen? Nachtrassler. Hunderte. Keiner traut sich mehr auf die Pfade": "Hoor je het geratel op de kliffen? Nachtratelaars. Honderden. Niemand durft de paden nog op",
"Moorpythons": "Veenpythons",
"Im Schwarzmoor würgen Pythons ganze Boote unter Wasser. Wer dort Torf sticht, kommt nicht wieder": "In het zwartveen wurgen pythons hele boten onder water. Wie daar turf steekt, komt niet terug",
"Panther im Nebel": "Panters in de nevel",
"Die Nebelpanther jagen für die Moornagas. Mach das Moor wieder sicher": "De nevelpanters jagen voor de veennaga's. Maak het veen weer veilig",
"Die lange Nacht": "De lange nacht",
"Mitternachtswölfe": "Middernachtwolven",
"Ysra hat dich geschickt? Gut. Mitternachtswölfe umkreisen die Terrassen, sie riechen jede Schwäche": "Heeft Ysra je gestuurd? Goed. Middernachtwolven omcirkelen de terrassen, ze ruiken elke zwakte",
"Der Dunkelyeti": "De duistere yeti",
"Dunkelyetis kommen nachts die Hänge herunter, so groß wie Hütten. Bring ihre Felle als Beweis": "Duistere yeti's komen 's nachts de hellingen af, zo groot als hutten. Breng hun vachten als bewijs",
"Zwei Steine des Frostes halten die Nacht fest. Zerschlage sie": "Twee stenen van de vorst houden de nacht vast. Sla ze kapot",
"Nachtmammuts": "Nachtmammoeten",
"Die Nachtmammuts sind rasend, seit kein Morgen mehr kommt. Sie zertrampeln unsere Vorratshütten": "De nachtmammoeten zijn razend sinds er geen ochtend meer komt. Ze vertrappen onze voorraadhutten",
"Frostgespenster": "Vorstspoken",
"In der Nacht wandern Gespenster aus Reif. Wer sie berührt, erfriert von innen": "'S Nachts dwalen spoken van rijp rond. Wie ze aanraakt, bevriest van binnenuit",
"Wo der Stein der Stille steht, verstummt sogar der Wind. Bring den Klang zurück": "Waar de steen van de stilte staat, verstomt zelfs de wind. Breng de klank terug",
"Heimkehr nach Mondfall": "Thuiskomst in Maanval",
"Allein oder mit der Gruppe in die Arena – und mit vollen Taschen zurück": "Alleen of met de groep de arena in – en met volle zakken terug",
